package com.example.jalalidaily;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
public class MainActivity extends Activity{
 LinearLayout root,days,items;TextView monthTitle;int year,month,day;String chosenSticker="📝";final int blue=Color.rgb(23,59,114);
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(blue);int[] j=Jalali.fromGregorian(LocalDate.now());year=j[0];month=j[1];day=j[2];if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},4);draw();}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(blue);t.setGravity(Gravity.CENTER);t.setPadding(9,12,9,12);return t;}
 void draw(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,18,16,12);root.setBackgroundColor(0xFFF5F7FC);setContentView(root);TextView heading=text("تقویم و یادداشت شمسی",23);heading.setTextColor(0xFF173B72);root.addView(heading);LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);root.addView(nav);Button prev=new Button(this);prev.setText("ماه قبل");nav.addView(prev);monthTitle=text("",19);nav.addView(monthTitle,new LinearLayout.LayoutParams(0,-2,1));Button next=new Button(this);next.setText("ماه بعد");nav.addView(next);prev.setOnClickListener(v->move(-1));next.setOnClickListener(v->move(1));days=new LinearLayout(this);days.setOrientation(1);root.addView(days);ScrollView sc=new ScrollView(this);items=new LinearLayout(this);items.setOrientation(1);sc.addView(items);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button add=new Button(this);add.setText("+ یادداشت جدید");root.addView(add);add.setOnClickListener(v->editor());renderCalendar();renderNotes();}
 void move(int delta){month+=delta;if(month>12){month=1;year++;}if(month<1){month=12;year--;}day=Math.min(day,Jalali.daysInMonth(year,month));renderCalendar();renderNotes();}
 void renderCalendar(){days.removeAllViews();monthTitle.setText(Jalali.MONTHS[month-1]+" "+year);String[] names={"ش","ی","د","س","چ","پ","ج"};LinearLayout hdr=new LinearLayout(this);for(String n:names){TextView t=text(n,14);hdr.addView(t,new LinearLayout.LayoutParams(0,-2,1));}days.addView(hdr);LocalDate first=Jalali.toGregorian(year,month,1);int offset=(first.getDayOfWeek().getValue()+1)%7;int count=Jalali.daysInMonth(year,month);for(int r=0;r<6;r++){LinearLayout line=new LinearLayout(this);for(int col=0;col<7;col++){int d=r*7+col-offset+1;TextView cell=text(d>=1&&d<=count?String.valueOf(d):"",15);if(d==day)cell.setBackgroundColor(0xFFDCEBFF);if(d>=1&&d<=count&&col==6)cell.setTextColor(0xFFD62839);if(d>=1&&d<=count)cell.setOnClickListener(v->{day=d;renderCalendar();showDayDialog();});line.addView(cell,new LinearLayout.LayoutParams(0,(int)(48*getResources().getDisplayMetrics().density),1));}days.addView(line);if((r+1)*7-offset>=count)break;}}
 void showDayDialog(){LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(18,10,18,10);ScrollView scroll=new ScrollView(this);scroll.addView(panel);String key=Jalali.key(new int[]{year,month,day});panel.addView(text("کارهای "+Jalali.label(new int[]{year,month,day}),20));ArrayList<JSONObject> list=Store.forDay(this,key);if(list.isEmpty())panel.addView(text("برای این روز کاری ثبت نشده",15));for(JSONObject o:list){LinearLayout line=new LinearLayout(this);line.setOrientation(1);line.setPadding(12,8,12,8);line.setBackgroundColor(0xFFEAF0FA);CheckBox done=new CheckBox(this);done.setText(o.optString("sticker","📝")+"  "+o.optString("time")+"  "+o.optString("title"));done.setTextSize(17);done.setTextColor(0xFF173B72);done.setChecked(o.optBoolean("done",false));done.setButtonTintList(android.content.res.ColorStateList.valueOf(0xFFE53935));done.setOnCheckedChangeListener((button,checked)->{Store.setDone(this,o.optLong("id"),checked);renderNotes();Widgets.refresh(this);});line.addView(done);line.addView(text(o.optString("body"),14));Button sticker=new Button(this);sticker.setText("انتخاب استیکر");line.addView(sticker);sticker.setOnClickListener(v->chooseSticker(s->{Store.setSticker(this,o.optLong("id"),s);showDayDialog();}));Button del=new Button(this);del.setText("حذف کار");line.addView(del);del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("این کار حذف شود؟").setNegativeButton("انصراف",null).setPositiveButton("حذف",(x,w)->{Store.delete(this,o.optLong("id"));showDayDialog();renderNotes();Widgets.refresh(this);}).show());panel.addView(line);}new AlertDialog.Builder(this).setView(scroll).setPositiveButton("+ کار جدید",(d,w)->editor()).setNegativeButton("بستن",null).show();}
 interface StickerChoice{void select(String sticker);}
 void chooseSticker(StickerChoice cb){String[] stickers={"📝","💼","📚","🏃","💊","🛒","🎉","❤️","📞","💰","🏠","⚽","⭐","🎯","🚗","🍎"};new AlertDialog.Builder(this).setTitle("انتخاب استیکر کار").setItems(stickers,(d,w)->cb.select(stickers[w])).show();}
 void renderNotes(){items.removeAllViews();items.addView(text("برنامه‌های "+Jalali.label(new int[]{year,month,day}),18));ArrayList<JSONObject> list=Store.forDay(this,Jalali.key(new int[]{year,month,day}));if(list.isEmpty())items.addView(text("برای دیدن یا ثبت کار، یک روز را لمس کنید",14));for(JSONObject o:list){TextView t=text((o.optBoolean("done")?"🔴 ✓ ":"○ ")+o.optString("sticker","📝")+" "+o.optString("time")+" "+o.optString("title"),16);t.setOnClickListener(v->showDayDialog());items.addView(t);}}
 void editor(){LinearLayout form=new LinearLayout(this);form.setPadding(25,10,25,0);form.setOrientation(1);EditText title=new EditText(this);title.setHint("عنوان یادداشت");form.addView(title);EditText body=new EditText(this);body.setHint("توضیحات");form.addView(body);Button stickerButton=new Button(this);stickerButton.setText("استیکر: "+chosenSticker);form.addView(stickerButton);stickerButton.setOnClickListener(v->chooseSticker(s->{chosenSticker=s;stickerButton.setText("استیکر: "+s);}));form.addView(text("ساعت یادآوری (اختیاری)",15));TimePicker picker=new TimePicker(this);picker.setIs24HourView(true);form.addView(picker);CheckBox remind=new CheckBox(this);remind.setText("ارسال اعلان در این ساعت");form.addView(remind);ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle(Jalali.label(new int[]{year,month,day})).setView(scroll).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(dialog,which)->{String t=title.getText().toString().trim();if(t.isEmpty()){Toast.makeText(this,"عنوان خالی است",Toast.LENGTH_SHORT).show();return;}int h=picker.getHour(),m=picker.getMinute();String time=String.format(Locale.US,"%02d:%02d",h,m);LocalDate date=Jalali.toGregorian(year,month,day);long at=date.atTime(h,m).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();long id=Store.add(this,Jalali.key(new int[]{year,month,day}),t,body.getText().toString(),time,at);Store.setSticker(this,id,chosenSticker);chosenSticker="📝";if(remind.isChecked()&&at>System.currentTimeMillis())schedule(id,t,body.getText().toString(),at);renderNotes();Widgets.refresh(this);}).show();}
 void schedule(long id,String title,String body,long at){Intent i=new Intent(this,ReminderReceiver.class);i.putExtra("title",title);i.putExtra("body",body);i.putExtra("id",(int)(id&0x7fffffff));PendingIntent pi=PendingIntent.getBroadcast(this,(int)(id&0x7fffffff),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}
 @Override protected void onResume(){super.onResume();Widgets.refresh(this);}
}